/** Evidence belongs to an opened SDK runtime, never to an instance-level version cache. */
export interface OpenCodeSessionEvidence {
  readonly protocol: "opencode-v1-sdk.sse" | "opencode-v2-http.sse";
  readonly version: string;
  readonly cwd: string;
  readonly homeDirectory: string;
  readonly external: boolean;
  readonly readLegacy: (input: {
    readonly nativeSessionId: string;
    readonly turnId?: string;
    readonly messageId?: string;
    readonly ensure: ProviderAdapterV2EnsureThreadInput;
  }) => Effect.Effect<ProviderAdapterV2ThreadSnapshot, unknown>;
  readonly adoptBuffered?: (input: {
    readonly request: ProviderContinuationRequest;
    readonly turn: Omit<ProviderAdapterV2TurnInput, "message">;
    readonly isCurrent: Effect.Effect<boolean, unknown>;
  }) => Effect.Effect<boolean, unknown>;
}

const sessionEvidence = new WeakMap<ProviderAdapterV2SessionRuntime, OpenCodeSessionEvidence>();

export const readOpenCodeSessionEvidence = (runtime: ProviderAdapterV2SessionRuntime) =>
  sessionEvidence.get(runtime);

/** Called only by the selected original v1/v2 adapter after its native connection is opened. */
export const bindOpenCodeSessionEvidence = (
  runtime: ProviderAdapterV2SessionRuntime,
  evidence: OpenCodeSessionEvidence,
): Effect.Effect<void, never, Scope.Scope> =>
  Effect.acquireRelease(
    Effect.sync(() => { sessionEvidence.set(runtime, evidence); }),
    () => Effect.sync(() => { sessionEvidence.delete(runtime); }),
  );
